import AppKit
import Combine
import QuartzCore

/// The mark: "ASMR" over "X_" in a sheared bitmap face (MenuBarGlyphs.swift, generated by
/// tools/icon/make_menubar.py), square and the size of an ordinary menu bar icon.
///   stopped      a dimmed template image; it follows the light or dark menu bar
///   playing      the same template, solid: calm, but plainly on
///   popover open a blue crest passes through the letters one by one, with a slight glow, and
///                the cursor blinks. With Reduce motion the letters are simply blue.
enum MenuBarIcon {
    static let size = MenuBarGlyphs.size
    /// One pass of the crest through the word, seconds.
    static let period: CFTimeInterval = 2.4

    static let stopped = template(alpha: 0.5)
    static let playing = template(alpha: 1.0)

    private static func template(alpha: CGFloat) -> NSImage {
        let image = NSImage(size: size, flipped: false) { _ in
            guard let ctx = NSGraphicsContext.current?.cgContext else { return false }
            ctx.addPath(MenuBarGlyphs.path)
            ctx.setFillColor(NSColor.black.withAlphaComponent(alpha).cgColor)
            ctx.fillPath()
            return true
        }
        image.isTemplate = true
        return image
    }

    /// One frame of the open state. Not a template: colours are resolved when drawn, against the
    /// status item's appearance, so the blue reads on light and dark bars alike.
    static func open(phase: CGFloat, cursor: Bool = true) -> NSImage {
        let image = NSImage(size: size, flipped: false) { _ in
            guard let ctx = NSGraphicsContext.current?.cgContext else { return false }
            let dark = NSAppearance.currentDrawing().bestMatch(from: [.darkAqua, .aqua]) == .darkAqua
            draw(in: ctx, dark: dark, phase: phase, cursor: cursor)
            return true
        }
        image.isTemplate = false
        return image
    }

    /// For letter `i` at `phase` in 0..<1: how far it is filled with blue, and how bright the
    /// passing crest is on it. The front fills the word in the first 60 % of the loop, the word
    /// holds, then lets the blue go before the next pass.
    static func wave(_ i: Int, phase: CGFloat) -> (fill: CGFloat, crest: CGFloat) {
        func smooth(_ a: CGFloat, _ b: CGFloat, _ x: CGFloat) -> CGFloat {
            let t = min(max((x - a) / (b - a), 0), 1)
            return t * t * (3 - 2 * t)
        }
        let n = CGFloat(MenuBarGlyphs.letters.count)
        let front = phase / 0.6 * (n + 1) - 0.5
        let d = front - CGFloat(i)
        // The cursor stays blue while open; it is where the next word will go.
        if i == MenuBarGlyphs.cursor { return (1, exp(-d * d / 0.3)) }
        let release = 1 - smooth(0.82, 1.0, phase)
        return (smooth(-0.35, 0.35, d) * release, exp(-d * d / 0.3) * release)
    }

    /// The whole word blue and still (Reduce motion).
    static let steadyPhase: CGFloat = 0.7

    static func draw(in ctx: CGContext, dark: Bool, phase: CGFloat, cursor: Bool = true) {
        // The bar's own text colour before the wave, blue after it, near-white blue in the crest.
        let base: (CGFloat, CGFloat, CGFloat, CGFloat) = dark ? (1, 1, 1, 0.92) : (0, 0, 0, 0.85)
        let blue: (CGFloat, CGFloat, CGFloat) = dark ? (0.36, 0.55, 1.0) : (0.13, 0.36, 1.0)
        let crestColour: (CGFloat, CGFloat, CGFloat) = dark ? (0.80, 0.88, 1.0) : (0.42, 0.62, 1.0)
        for (i, letter) in MenuBarGlyphs.letterPaths.enumerated() {
            if i == MenuBarGlyphs.cursor && !cursor { continue }
            let w = wave(i, phase: phase)
            func mix(_ a: CGFloat, _ b: CGFloat, _ t: CGFloat) -> CGFloat { a + (b - a) * t }
            let r = mix(mix(base.0, blue.0, w.fill), crestColour.0, w.crest)
            let g = mix(mix(base.1, blue.1, w.fill), crestColour.1, w.crest)
            let b = mix(mix(base.2, blue.2, w.fill), crestColour.2, w.crest)
            let a = mix(base.3, 1, max(w.fill, w.crest))
            ctx.saveGState()
            let glow = 0.25 * w.fill + 0.75 * w.crest
            if glow > 0.02 {
                ctx.setShadow(offset: .zero, blur: 0.6 + 1.6 * glow,
                              color: CGColor(srgbRed: 0.3, green: 0.5, blue: 1.0, alpha: min(1, glow)))
            }
            ctx.addPath(letter)
            ctx.setFillColor(CGColor(srgbRed: r, green: g, blue: b, alpha: a))
            ctx.fillPath()
            ctx.restoreGState()
        }
    }
}

/// Publishes the current menu bar image. A ~30 fps timer runs only while the popover is open.
final class MenuBarIconAnimator: ObservableObject {
    @Published private(set) var image: NSImage = MenuBarIcon.stopped
    private var timer: Timer?

    var playing = false {
        didSet { if playing != oldValue && !open { image = resting } }
    }

    var open = false {
        didSet {
            guard open != oldValue else { return }
            open ? start() : stop()
        }
    }

    private var resting: NSImage { playing ? MenuBarIcon.playing : MenuBarIcon.stopped }

    private func start() {
        if Motion.reduced {
            image = MenuBarIcon.open(phase: MenuBarIcon.steadyPhase)
            return
        }
        tick()
        let t = Timer(timeInterval: 1.0 / 30.0, repeats: true) { [weak self] _ in self?.tick() }
        t.tolerance = 0.005
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    private func stop() {
        timer?.invalidate()
        timer = nil
        image = resting
    }

    private func tick() {
        let now = CACurrentMediaTime()
        let blink = now.truncatingRemainder(dividingBy: 1.1) < 0.6
        image = MenuBarIcon.open(phase: CGFloat(now.truncatingRemainder(dividingBy: MenuBarIcon.period) / MenuBarIcon.period),
                                 cursor: blink)
    }

    deinit { timer?.invalidate() }
}
